            missing = os.path.join(tmp, "new.jsonl")
            proc = run_chain(base_request(), missing)
            self.assertEqual(proc.returncode, 0, proc.stderr)
            self.assertTrue(os.path.exists(missing))
            # 空文件视为合法空链。
