PATIENT_GENDERS = ("male", "female", "other", "unknown")

_FHIR_DATE_RE = re.compile(r"^(\d{4})-(\d{2})-(\d{2})$")
# ISO8601：YYYY-MM-DD，可带 Thh:mm[:ss[.f...]] 与 Z 或 ±hh:mm 时区。
_FHIR_DATETIME_RE = re.compile(
    r"^(\d{4})-(\d{2})-(\d{2})"
    r"(?:T([01]\d|2[0-3]):([0-5]\d)(?::([0-5]\d)(?:\.\d+)?)?"
    r"(Z|[+-](?:[01]\d|2[0-3]):[0-5]\d)?)?$"
)


def _valid_ymd(year, month, day):
    try:
        datetime.date(int(year), int(month), int(day))
    except ValueError:
        return False
    return True


def _is_fhir_date(value):
    """YYYY-MM-DD 且为真实存在的日期。"""
    if not isinstance(value, str):
        return False
    match = _FHIR_DATE_RE.fullmatch(value)
    return bool(match) and _valid_ymd(*match.groups())


def _is_fhir_datetime(value):
    """ISO8601 日期或日期时间，日期部分必须真实存在。"""
    if not isinstance(value, str):
        return False
    match = _FHIR_DATETIME_RE.fullmatch(value)
    return bool(match) and _valid_ymd(*match.group(1, 2, 3))


