    """CodeableConcept：对象；coding 为对象数组，其 system/code/display 为
    字符串、userSelected 为布尔（字段出现即检查，null 与形状错误一律拒绝）。"""
    if not isinstance(value, dict):
        raise FhirValidationError("%s 必须为 CodeableConcept 对象" % label)
    if "coding" in value:
        coding = value["coding"]
        if not isinstance(coding, list):
            raise FhirValidationError("%s.coding 必须为对象数组" % label)
        for pos, item in enumerate(coding):
            item_label = "%s.coding[%d]" % (label, pos)
